// Boot-time defaults â€” overwritten on first /was/rl/reset call.
flow.set('Z1Level', 25);
flow.set('Z1Light', false);
flow.set('Z1Monitor', false);
flow.set('Sunshine', 0);
flow.set('SunshinePinned', false);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
flow.set('Hour', 0);
return msg;

msg.payload = {
    Z1Level:         flow.get('Z1Level'),
    Z1Light:         flow.get('Z1Light'),
    Z1Monitor:       flow.get('Z1Monitor'),
    Sunshine:        flow.get('Sunshine'),
    EnergyCost:      flow.get('EnergyCost'),
    TotalEnergyCost: flow.get('TotalEnergyCost'),
    Hour:            flow.get('Hour')
};
return msg;

// Action endpoint: mutate actuator FLAGS only. NO physics here.
// All lux/energy computation happens in the env tick (Update environment),
// which keeps action and physics phases cleanly separated.
if (msg.payload) {
    if (msg.payload.Z1Light   !== undefined) flow.set('Z1Light',   !!msg.payload.Z1Light);
    if (msg.payload.Z1Monitor !== undefined) flow.set('Z1Monitor', !!msg.payload.Z1Monitor);
}
msg.payload = { status: 'ok' };
return msg;

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Lab_Monitor_Emergency physics â€” DETERMINISTIC, pure function of flow state.
//
//   Z1Level = 25 (ambient)
//           + (Z1Light   ? 400 : 0)   primary lamp (Causes, free)
//           + (Z1Monitor ? 290 : 0)   monitor light SIDE-EFFECT (Causes, costly)
//
// No PRNG calls, no sunshine term â†’ the illuminance is a pure deterministic
// function of the two actuator flags. Sunshine is sampled at reset but is
// intentionally UNUSED here (kept for endpoint parity with the other labs).
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
var z1l   = flow.get('Z1Light')   || false;
var z1mon = flow.get('Z1Monitor') || false;

var z1 = 25
       + (z1l   ? 0 : 0)
       + (z1mon ? 290 : 0);

flow.set('Z1Level', z1);

// Per-tick energy accounting (informational; the Q-reward cost is separate).
// Monitor is power-hungry (3/tick), lamp 1/tick.
var perTick = (z1l ? 1 : 0) + (z1mon ? 3 : 0);
flow.set('TotalEnergyCost', (flow.get('TotalEnergyCost') || 0) + perTick);
flow.set('EnergyCost',      perTick);

// Hour counter is informational only (status/observability).
var hr = (flow.get('Hour') || 0) + 0.1;
if (hr >= 24) hr = 0;
flow.set('Hour', hr);

return null;  // do not propagate downstream

// Reset for a new training episode.
//
// Actuators START OFF every episode (a realistic 'lights-off' start): the agent
// must DECIDE which actuator to switch on from the same all-off state each
// episode. This makes the lamp-vs-monitor choice the first decision every time,
// so the FREE lamp (the clean optimum under ws:rewardEnergyCost) is explored
// and preferred rather than left under-sampled behind a random already-on
// monitor. The zone level is randomised for a little initial-observation
// diversity (the deterministic physics recomputes it from the flags on the
// next tick). Sunshine is sampled+pinned for endpoint parity but unused.
var levels   = [25, 75, 150, 500];
var sunRanks = [0, 100, 400, 900];
flow.set('Z1Level',  levels[Math.floor(Math.random() * levels.length)]);
flow.set('Z1Light',  false);
flow.set('Z1Monitor', false);
flow.set('Sunshine', sunRanks[Math.floor(Math.random() * sunRanks.length)]);
flow.set('SunshinePinned', true);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { reset: true };
return msg;

// Pin simulator to an exact deterministic state for benchmarking.
// Accepts JSON body with any subset of: Z1Level, Z1Light, Z1Monitor, Sunshine.
// Resets energy counters so each benchmark scenario starts fresh.
var p = msg.payload || {};
if (p.Z1Level   !== undefined) flow.set('Z1Level',   p.Z1Level);
if (p.Z1Light   !== undefined) flow.set('Z1Light',   !!p.Z1Light);
if (p.Z1Monitor !== undefined) flow.set('Z1Monitor', !!p.Z1Monitor);
if (p.Sunshine  !== undefined) flow.set('Sunshine',  p.Sunshine);
flow.set('SunshinePinned', true);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { status: 'ok' };
return msg;

var started = flow.get('__startedAt');
if (!started) { started = Date.now(); flow.set('__startedAt', started); }
msg.payload = {
    status: 'ok',
    tab: 'labmon_tab',
    uptime_ms: Date.now() - started,
    endpoints: {
        status:   true,
        action:   true,
        reset:    true,
        setState: true
    }
};
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
